<template><main class="sewp-page"><div class="sewp-heading-row"><div><p class="sewp-kicker">SEWP RFQ PORTAL</p><h1>Create RFQ</h1><p>Register an opportunity and start intake.</p></div><SewpPortalNav/></div><div class="sewp-cui-warning"><ShieldAlert :size="18"/> Do not enter or upload CUI.</div><form class="sewp-panel sewp-form" @submit.prevent="submit"><div class="sewp-form-section"><h2>Opportunity information</h2><p>Fields marked with an asterisk are required.</p></div><label><span>Official RFQ Number *</span><input v-model.trim="form.officialRfqNumber" required/></label><label><span>Title *</span><input v-model.trim="form.title" required/></label><label><span>Agency</span><input v-model.trim="form.agency"/></label><label><span>Customer Organization</span><input v-model.trim="form.customerOrganization"/></label><label><span>Source *</span><select v-model="form.source"><option>SEWP</option><option>Manual</option><option>SAM.gov</option></select></label><label><span>Category</span><input v-model.trim="form.category"/></label><label><span>Priority</span><select v-model="form.priority"><option>Low</option><option>Normal</option><option>High</option><option>Critical</option></select></label><label><span>Set-Aside</span><input v-model.trim="form.setAside"/></label><label><span>Questions Due</span><input v-model="form.questionsDueAt" type="datetime-local"/></label><label><span>Response Due</span><input v-model="form.responseDueAt" type="datetime-local"/></label><label><span>Estimated Value</span><input v-model.number="form.estimatedValue" min="0" step=".01" type="number"/></label><label class="wide"><span>Internal Notes</span><textarea v-model.trim="form.notes" rows="4"/></label><div v-if="error" class="sewp-alert error wide">{{error}}</div><div class="sewp-form-actions wide"><RouterLink class="secondary-action" to="/sewp-rfqs/work-queue">Cancel</RouterLink><button class="primary-action" :disabled="saving">{{saving?'Creating…':'Create RFQ'}}</button></div></form></main></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ShieldAlert}from'@lucide/vue';import SewpPortalNav from'../components/SewpPortalNav.vue';import{createSewpRfq}from'../services/sewpApi';import type{SewpCreateInput}from'../types/sewp';const router=useRouter(),saving=ref(false),error=ref('');const form=reactive({officialRfqNumber:'',title:'',agency:'',customerOrganization:'',source:'SEWP',category:'',setAside:'',priority:'Normal' as SewpCreateInput['priority'],questionsDueAt:'',responseDueAt:'',estimatedValue:null as number|null,notes:''});async function submit(){saving.value=true;error.value='';try{const{record}=await createSewpRfq({...form,questionsDueAt:form.questionsDueAt?new Date(form.questionsDueAt).toISOString():null,responseDueAt:form.responseDueAt?new Date(form.responseDueAt).toISOString():null,responseTimeZone:'America/New_York'});await router.push(`/sewp-rfqs/${record.id}`)}catch(e){error.value=e instanceof Error?e.message:'Unable to create RFQ.'}finally{saving.value=false}}</script>
